using System;using System.IO;
class BrandMigrationTests {
 static void Main(){string root=Path.Combine(Path.GetTempPath(),"brand-test-"+Guid.NewGuid());string old=Path.Combine(root,"LumeRGB"),current=Path.Combine(root,"ThebestRGB");Directory.CreateDirectory(old);Directory.CreateDirectory(current);File.WriteAllText(Path.Combine(old,"profiles.json"),"old profile");File.WriteAllText(Path.Combine(old,"palette.json"),"palette");File.WriteAllText(Path.Combine(current,"profiles.json"),"new profile");BrandMigration.MigrateData(root);if(File.ReadAllText(Path.Combine(current,"profiles.json"))!="new profile"||File.ReadAllText(Path.Combine(current,"palette.json"))!="palette"||!File.Exists(Path.Combine(old,"profiles.json")))throw new Exception("Migration lost data");File.WriteAllText(Path.Combine(old,"later.json"),"old");BrandMigration.MigrateData(root);if(File.Exists(Path.Combine(current,"later.json")))throw new Exception("Migration repeated");Console.WriteLine("PASS: legacy settings copied once, existing and original files preserved.");}
}
